#!/bin/sh

# Reject direct pushes to main/develop (they only change through a merged PR)
# and to server (generated by .github/workflows/server-branch.yml), then run every check.
# Exception: main can be pushed to the gitlab mirror after a promotion.
# Install: cp .githooks/pre-push.sh .git/hooks/pre-push && chmod +x .git/hooks/pre-push

remote="$1"
protected="main develop server"

while read -r _local_ref _local_sha remote_ref _remote_sha; do
    branch=$(printf '%s' "$remote_ref" | sed 's#refs/heads/##')
    if [ "$remote" = "gitlab" ] && [ "$branch" = "main" ]; then
        continue
    fi
    for p in $protected; do
        if [ "$branch" = "$p" ]; then
            echo "✖ Direct push to '$p' on '$remote' is forbidden."
            echo "  Use a <type>/* branch + a Pull Request."
            exit 1
        fi
    done
done

# Every test, the Cinnamon checks and shellcheck (scripts/check-all.sh, under a minute).
# --no-verify skips this hook, as any other.
repo_root="$(git rev-parse --show-toplevel)"
if [ -x "$repo_root/scripts/check-all.sh" ]; then
    if ! "$repo_root/scripts/check-all.sh"; then
        echo "✖ scripts/check-all.sh failed: push cancelled."
        exit 1
    fi
fi

exit 0
